// CSD_RATIONALE_BEGIN
// Attempt 7: Attempt-2 basis with two targeted improvements.
//
// Root-cause analysis of 9 final_span_unclosed failures:
//   A) The prompt prohibits ** which IS needed for correct answers like n0*(r+1)**d.
//      Models fall back to ^ (XOR, not in grammar) causing dead ends.
//   B) Models write comparisons (>, <, ==) and assignments (=, :=) inside spans
//      (e.g., <<n1 =, <<100*int(sides>target). These lead to partially-open
//      expressions that can never reach a complete parse state.
//   C) When SafeRepetitionPenaltyStep returns EOS inside a constrained span, the
//      current code breaks with currentConstrainedOut still at a possibly-incomplete
//      mid-expression state. CloseSpanWithinBudget then starts from a hard-to-close
//      prefix (e.g., ["100","*","(","(","(","int","(","sides",">"]), often failing.
//
// Fixes:
//   Fix A: Updated prompt: allow **, forbid >, <, ==, !=, >=, <=, =, if, else, ^.
//   Fix B: On EOS-inside-span, call RollbackConstrainedToComplete BEFORE breaking
//      so the cleanup CloseSpanWithinBudget starts from the last complete prefix
//      (e.g., ["n1"] or ["100"]) rather than a mid-expression dead-end state.
//   Unchanged: SafeRepetitionPenaltyStep(4.0) for constrained steps (key from attempt 2),
//      closeReserve=80, free UnconstrainedStep + RenderedEndsWith detection,
//      IsCompletePrefix check for immediate graceful close, final cleanup block.
//   Specifically NOT added: DeadEndDetection (attempt 6 showed this hurt accuracy -4.1pp).
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (closeReserve branch): CloseSpanWithinBudget postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut) for both the closed (vacuous)
//     and open (still-valid prefix) exit paths. ✓
//
//   (outside span + << detected): We set currentConstrainedOut := [], and
//     parser.IsValidPrefix([]) holds by method precondition. The implication was
//     vacuous before the flip; it is directly satisfied after. ✓
//
//   (outside span + no << or EOS): insideConstrainedOut stays false, implication
//     remains vacuous. ✓
//
//   (IsCompletePrefix close): CloseConstrainedSpan sets insideConstrainedOut := false,
//     so the implication becomes vacuously true. ✓
//
//   (EOS-inside-span rollback): RollbackConstrainedToComplete postcondition guarantees
//     parser.IsValidPrefix(rc). We assign currentConstrainedOut := rc while
//     insideConstrainedOut stays true, so the implication is preserved directly. ✓
//
//   (normal constrained step, non-EOS): SafeRepetitionPenaltyStep hard-masks to
//     parser-valid tokens plus EOS; when next != eosToken it is parser-valid.
//     AppendConstrainedToken postcondition asserts parser.IsValidPrefix(appendedCurrent). ✓
//
//   (final cleanup): Same CloseSpanWithinBudget postcondition as closeReserve branch. ✓
//
// Invariant 2 — progress:
//   |generated| <= |generatedPrefix| + steps
//
//   (closeReserve, s=steps_before): CloseSpanWithinBudget(remaining) postcondition gives
//     |cg| <= |generated| + remaining = |generated| + (maxSteps - s).
//     By invariant: |cg| <= |generatedPrefix| + s + (maxSteps - s) = |generatedPrefix| + maxSteps.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   (outside + token appended): steps grows by 1; exactly one token appended. ✓
//   (outside + EOS/no-<<): steps grows by 1; generated unchanged or no span token. ✓
//   (IsCompletePrefix close): steps grows by 1; CloseConstrainedSpan appends at most
//     one ">>" token. |cg| <= |generated| + 1 <= |generatedPrefix| + steps. ✓
//   (EOS rollback): steps already incremented by 1 for the EOS cost.
//     RollbackConstrainedToComplete shrinks or preserves generated: |rg| <= |generated_before|.
//     |generated_after| = |rg| <= |generated_before| <= |generatedPrefix| + steps. ✓
//   (normal step + AppendConstrainedToken): steps grows by 1; exactly one token appended.
//     |appendedGenerated| = |generated| + 1 <= |generatedPrefix| + steps. ✓
//   (final cleanup): Same CloseSpanWithinBudget argument as closeReserve branch. ✓
// CSD_PROOF_SKETCH_END
generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "Wrap every intermediate symbolic expression in << >> delimiters. " +
  "For the final answer, write: The final answer is <<symbolic expression>>. " +
  "Inside << >> use ONLY: numbers, variable names from the problem, +, -, *, **, /, //, %, (), int(). " +
  "Do NOT use inside << >>: =, >, <, >=, <=, ==, !=, if, else, while, ^, or, and, not, :=. " +
  "Use int() when the result must be a whole number. " +
  "Use // for floor division. Use ** for exponentiation (not ^). " +
  "Use exact variable names from the problem. Do not substitute numeric values for variables.");

var closeReserve: nat := 80;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget running low inside a span: force-close using dead-end-aware helper
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    }
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.SafeRepetitionPenaltyStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, generated, 4.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // EOS inside span: roll back to last complete prefix so cleanup starts cleanly
      var rg, rc := helpers.RollbackConstrainedToComplete(parser, generated, currentConstrainedOut);
      generated := rg;
      currentConstrainedOut := rc;
      // insideConstrainedOut remains true; final cleanup will close the span
      break;
    }
    var ag, ai, ac := helpers.AppendConstrainedToken(
      lm, parser, generated, currentConstrainedOut, next
    );
    generated := ag;
    insideConstrainedOut := ai;
    currentConstrainedOut := ac;
  }
}

// Final cleanup: close any remaining open span with all available remaining budget
if insideConstrainedOut && steps < maxSteps {
  var remaining2: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining2
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

